func RunJSONSerializationTestForTlsProperties_STATUS(t *rapid.T) {
	subject := TlsProperties_STATUSGenerator().Draw(t, "subject")
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		t.Fatal(err)
	}

	// Deserialize back into memory
	var actual TlsProperties_STATUS
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		t.Fatal(err)
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		t.Error(result)
	}
}

// Generator of TlsProperties_STATUS instances for property testing - lazily instantiated by
// TlsProperties_STATUSGenerator()
var tlsProperties_STATUSGenerator *rapid.Generator[TlsProperties_STATUS]

// TlsProperties_STATUSGenerator returns a generator of TlsProperties_STATUS instances for property testing.
func TlsProperties_STATUSGenerator() *rapid.Generator[TlsProperties_STATUS] {
	if tlsProperties_STATUSGenerator != nil {
		return tlsProperties_STATUSGenerator
	}

	certificate := rapid.Ptr(TlsCertificateProperties_STATUSGenerator(), true)
	status := rapid.Ptr(rapid.SampledFrom([]TlsStatus_STATUS{TlsStatus_STATUS_Disabled, TlsStatus_STATUS_Enabled}), true)

	tlsProperties_STATUSGenerator = rapid.Custom(func(t *rapid.T) TlsProperties_STATUS {
		var result TlsProperties_STATUS
		result.Certificate = certificate.Draw(t, "Certificate")
		result.Status = status.Draw(t, "Status")
		return result
	})

	return tlsProperties_STATUSGenerator
}
